import concurrent.futures, urllib.request, hashlib, json, re
base='https://raw.githubusercontent.com/openmm/openmm/53770948682c40bd460b39830d4e0f0fd3a4b868/'
urls={'pdb':base+'examples/5dfr_solv-cube_equil.pdb','benchmark':base+'examples/benchmark.py','blog':'https://developer.nvidia.com/blog/maximizing-openmm-molecular-dynamics-throughput-with-nvidia-multi-process-service/','openmm':'https://pypi.org/pypi/openmm/8.2.0/json','cuda':'https://pypi.org/pypi/OpenMM-CUDA-12/8.2.0/json','platform':'https://docs.openmm.org/8.2.0/userguide/library/04_platform_specifics.html'}
def get(k,u):
 try:
  b=urllib.request.urlopen(u,timeout=25).read(); s=b.decode(); out={'source':u,'bytes':len(b),'sha256':hashlib.sha256(b).hexdigest()}
  if k=='pdb': out['atoms']=sum(l.startswith(('ATOM  ','HETATM')) for l in s.splitlines())
  elif k in ('openmm','cuda'):
   j=json.loads(s);out['requires_dist']=j['info']['requires_dist'];out['wheels']=[{'name':f['filename'],'bytes':f['size'],'sha256':f['digests']['sha256']} for f in j['urls'] if 'manylinux' in f['filename']]
  elif k=='benchmark':out['text']=s
  else:
   s=re.sub('<["'^>]+>'"',' ',s);s=re.sub(r'\\s+',' ',s)
   terms=['more than double','15–25','15 – 25','5 µs','5 μs','DeterministicForces','CUDA_MPS_ACTIVE_THREAD_PERCENTAGE','python benchmark.py','June 4, 2025']
   out['excerpts']=[s[max(0,m.start()-180):m.end()+280] for term in terms for m in list(re.finditer(re.escape(term),s))[:3]]
  return k,out
 except Exception as e:return k,{'source':u,'error':str(e)}
with concurrent.futures.ThreadPoolExecutor(max_workers=6) as pool:
 for k,o in pool.map(lambda kv:get(*kv),urls.items()):print(json.dumps({k:o}))
PY"

